#!/usr/bin/env bash
# run-query.sh <label> <fileset.txt> <request.json>
#
# Builds a guessless query document from a file set + request, runs it through the
# already-built CLI, writes <label>.receipt.json next to this script, and prints
# wall time (ms) and receipt byte size to stderr.
#
# Reads markless read-only. Writes only inside this evidence directory (+ scratch).
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GUESSLESS="/Users/jacksm5pro/dev/open-source/guessless"
MARKLESS="/Users/jacksm5pro/dev/open-source/markless"

LABEL="$1"; FILESET="$2"; REQUEST="$3"
DOC="$HERE/$LABEL.query.json"
OUT="$HERE/$LABEL.receipt.json"

node "$HERE/build-query.mjs" --root "$MARKLESS" --files "$HERE/$FILESET" --request "$HERE/$REQUEST" --out "$DOC" || exit 1

START=$(node -e 'process.stdout.write(String(Date.now()))')
node "$GUESSLESS/packages/cli/dist/cli.js" query "$DOC" > "$OUT" 2>"$OUT.stderr"
STATUS=$?
END=$(node -e 'process.stdout.write(String(Date.now()))')

BYTES=$(wc -c < "$OUT" | tr -d ' ')
echo "[$LABEL] exit=$STATUS wall_ms=$((END-START)) receipt_bytes=$BYTES" >&2
if [ -s "$OUT.stderr" ]; then echo "[$LABEL] stderr:" >&2; cat "$OUT.stderr" >&2; fi
rm -f "$OUT.stderr"
=== build-query ===
#!/usr/bin/env node
// build-query.mjs -- emit a guessless query document from a file list + request JSON.
//
// Usage:
//   node build-query.mjs --root <repoRoot> --files <fileListPath> --request <requestJsonPath> [--out <path>]
//
// The file list is one repo-relative path per line (blank lines and #-comments ignored).
// Each listed file is read verbatim from <repoRoot>/<path> and supplied as an input with
// `path` set to exactly the repo-relative string, so the engine sees the same file set the
// ground-truth audit was computed over.
//
// The repo root is only ever read from. This script never writes into it.

import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

function arg(name, fallback) {
	const i = process.argv.indexOf(`--${name}`);
	if (i === -1) {
		if (fallback === undefined) throw new Error(`missing --${name}`);
		return fallback;
	}
	return process.argv[i + 1];
}

const root = arg('root');
const filesPath = arg('files');
const requestPath = arg('request');
const out = arg('out', '-');

const paths = readFileSync(filesPath, 'utf8')
	.split('\n')
	.map((line) => line.trim())
	.filter((line) => line.length > 0 && !line.startsWith('#'));

const inputs = paths.map((p) => ({ path: p, source: readFileSync(join(root, p), 'utf8') }));
const request = JSON.parse(readFileSync(requestPath, 'utf8'));

const doc = JSON.stringify({ inputs, request });
if (out === '-') process.stdout.write(doc);
else writeFileSync(out, doc);
